#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);}
vector<int>color(n+1,0);bool cyc=false;
for(int s=1;s<=n&&!cyc;++s){
if(color[s])continue;
vector<pair<int,int>>st;st.push_back({s,0});color[s]=1;
while(!st.empty()&&!cyc){
auto&pr=st.back();
int u=pr.first;
if(pr.second<(int)g[u].size()){
int v=g[u][pr.second];++pr.second;
if(color[v]==1){cyc=true;break;}
if(color[v]==0){color[v]=1;st.push_back({v,0});}}
else{color[u]=2;st.pop_back();}}}
printf("%s\n",cyc?"YES":"NO");return 0;}

